(()=>{const bs=T.BattleScene;const out={};const fails=[];const CHK=(k,v)=>{out[k]=v;if(v!==true)fails.push(k+':'+JSON.stringify(v));};
if(!bs)return JSON.stringify({noBattle:true,allOk:false,fails:['no-battle']});
const a=bs.partyMembers[0];const e=bs.troop.aliveMembers()[0];
// 1) 行动顺序: turnAddSpeed 降序
for(const b of [...bs.partyMembers,...bs.troop.aliveMembers()])b.makeSpeed();
const all=[...bs.partyMembers.filter(x=>!x.isDead()),...bs.troop.aliveMembers()].sort((x,y)=>y.turnAddSpeed-x.turnAddSpeed);
let ordOk=true;for(let i=1;i<all.length;i++)if(all[i-1].turnAddSpeed<all[i].turnAddSpeed)ordOk=false;
CHK('speedSort',ordOk);
out.speedOrder=all.map(b=>b.name+':'+b.turnAddSpeed).join('|');
// 2) 会心率 clamp [0,0.5]
out.crit=bs.critChance(a,e);CHK('critClamp',out.crit>=0&&out.crit<=0.5);
// 3) 阵型速度加成参与 agi(雁行阵 agi 1.8)
const agi0=a.agi;T.$gameParty.setFormation(8);const agi1=a.agi;T.$gameParty._formation=-1;out.agiBoost=agi1-agi0;
CHK('formationAgi',Math.round(agi0*1.8)===agi1&&agi1>agi0);
out.allOk=fails.length===0;out.fails=fails;
return JSON.stringify(out);})()
